#include "core.h"   /* core.c: no stdio.h, no stdlib.h, no time.h */
static Quote price(const CartIn *in) {   /* pure: reads only its input */
    Quote q;
    q.total = in->qty * in->unit_cents;
    if (in->promo) q.total -= q.total / 10;
    q.tax = q.total / 10;
    return q; }                          /* by value: the caller owns it */
/* shell.c - the only file that touches the world */
int main(void) {
    CartIn in; if (!read_cart(stdin, &in)) return 1;
    Quote q = price(&in);
    printf("%d\n", q.total + q.tax); }
